effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  float ar = acScreenSize.x / max(acScreenSize.y, 1.0);
  vec2 p = (uv - 0.5) * vec2(ar, 1.0) * scale;
  float r2 = dot(p, p);
  p *= (1.0 + strength * r2 * mixAmt);
  uv = p / vec2(ar, 1.0) + 0.5;
  gl_FragColor = texture2DCv(inputImg.texture, uv);
}
